import { registerBlockType } from '@wordpress/blocks';
import { RichText, BlockControls, InspectorControls } from '@wordpress/block-editor';
import { CustomInnerButton } from './component/CustomInner';
import { TextControl, TextareaControl } from '@wordpress/components';

const variations = [
    {
        name: 'normal',
        title: '通常サイズ',
        className: 'c-text__normal'
    },
    {
        name: 'titleReg',
        title: '18px',
        className: 'c-text__title-reg'
    },
    {
        name: 'title',
        title: '18px 太文字',
        className: 'c-text__title'
    },
    {
        name: 'longHeight',
        title: '行間高め',
        className: 'c-text__long-height'
    }
];

const fontfamilys = [
    {
        name: 'jp',
        title: '日本語フォント',
        className: ''
    },
    {
        name: 'jp2',
        title: '日本語フォント(セリフ)',
        className: 'c-text--jp2'
    },
    {
        name: 'en',
        title: '英語フォント',
        className: 'c-text--en'
    },
];

const Familys = ({ fontfamily, setAttributes }) => {
    return (
        <>
            <select
                value={fontfamily}
                onChange={(event) => setAttributes({ fontfamily: event.target.value })}
            >
                {fontfamilys.map((item, index) => {
                    return (
                        <option key={index} value={item.className}>
                            {item.title}
                        </option>
                    );
                })}
            </select>
        </>
    )
}

const Variation = ({ variation, setAttributes }) => {
    return (
        <>
            <select
                value={variation}
                onChange={(event) => setAttributes({ variation: event.target.value })}
            >
                {variations.map((item, index) => {
                    return (
                        <option key={index} value={item.className}>
                            {item.title}
                        </option>
                    );
                })}
            </select>
        </>
    );
};

registerBlockType('portart/bodytext', {
    title: '本文',
    icon: 'smiley',
    category: 'layout',
    attributes: {
        text: {
            type: 'string',
            default: '',
        },
        text_en: {
            type: 'string',
            default: ''
        },
        variation: {
            type: 'string',
            default: 'c-text__normal',
        },
        fontfamily: {
            type: 'string',
            default: ''
        },
        addClassName: {
            type: 'string',
            default: '',
        },
        addId: {
            type: 'string',
            default: '',
        }
    },

    edit: ({ className, attributes, attributes: { text, text_en, variation, fontfamily, addClassName, addId }, setAttributes }) => {
        const onChangeClass = (newText) => {
            setAttributes({
                addClassName: newText
            });
        }
        const onChangeId = (newId) => {
            setAttributes({
                addId: newId
            });
        }
        console.log(text_en);

        return (
            <div>
                <BlockControls>
                    <Variation variation={variation} setAttributes={setAttributes} />
                    <Familys fontfamily={fontfamily} setAttributes={setAttributes} />
                    <CustomInnerButton attributes={attributes} setAttributes={setAttributes} />
                </BlockControls>
                <InspectorControls>
                    <TextareaControl
                        label="追加class"
                        value={addClassName}
                        onChange={onChangeClass}
                    />
                    <TextControl
                        label="追加Id"
                        value={addId}
                        onChange={onChangeId}
                    />
                </InspectorControls>

                <div className='b-wrapper__flex'>
                    <p className='opacity'>Ja:</p>
                    <RichText
                        value={text}
                        onChange={(v) => setAttributes({ text: v })}
                        tagName='p'
                        placeholder="本文を入力してください"
                        keepPlaceholderOnFocus
                        inlineToolbar
                        id="attr-text"
                    />
                </div>

                <div className='b-wrapper__flex'>
                    <p className='opacity'>En:</p>
                    <RichText
                        value={text_en}
                        onChange={(v) => setAttributes({ text_en: v })}
                        tagName='p'
                        placeholder="英文を入力してください"
                        keepPlaceholderOnFocus
                        inlineToolbar
                        id="attr-text-en"
                    />
                </div>

            </div>
        )
    },
    save: () => {
        return null;
    }
});